contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        require(loanToCollateral_ != 0);

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        bool activeBefore = c.isActive(0); if (__ESBMC_reverted()) return;
        require(activeBefore);

        c.rescindRequest(0); if (__ESBMC_reverted()) return;

        bool activeAfter = c.isActive(0); if (__ESBMC_reverted()) return;
        assert(!activeAfter);
    }

    receive() external payable {}
}

