pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(loanToCollateral_ != 0);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        bool activeBefore;
        try c.isActive(0) returns (bool __r) { activeBefore = __r; } catch { return; }
        vm.assume(activeBefore);
        try c.rescindRequest(0) {} catch { return; }
        bool activeAfter;
        try c.isActive(0) returns (bool __r) { activeAfter = __r; } catch { return; }
        assertTrue(!activeAfter);
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
